#' Item Order (Exploratory)
#'
#' Looks for order among yes/no items without a hypothesis: which items form a 
#' cumulative line, which are interchangeable, which branch and which stand 
#' apart. Combines Mokken-type scales, implications between items drawn as a 
#' Hasse diagram, and the answer patterns.
#' 
#'
#' @examples
#' \donttest{
#' data('wizlab', package = 'psyWiz')
#' psyWiz::itemOrder(wizlab, vars = c('debt_family', 'debt_friends', 'debt_bank',
#'                                    'debt_card', 'debt_lender', 'debt_mortgage'))
#'}
#' @param data the data as a data frame
#' @param vars a vector of strings naming the items
#' @param tolerance a number (default 10): 'A implies B' is accepted when at
#'   most this percentage of those who endorse A do not endorse B
#' @param hMin a number (default 0.30), the smallest Loevinger H for an
#'   implication and for joining a scale
#' @param showHasse \code{TRUE} (default) or \code{FALSE}, draw the order as a
#'   Hasse diagram
#' @param showImplications \code{TRUE} (default) or \code{FALSE}, list the
#'   direct implications
#' @param showScales \code{TRUE} (default) or \code{FALSE}, list the
#'   cumulative scales and the unscalable items
#' @param showPatterns \code{TRUE} or \code{FALSE} (default), list the most
#'   frequent answer patterns
#' @param patternsN an integer (default 10), how many patterns
#' @param highlight \code{TRUE} or \code{FALSE} (default), show item H below
#'   the smallest H in red
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reading} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$fitTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$itemTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hasse} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$implications} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$scales} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$patterns} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$fitTable$asDF}
#'
#' \code{as.data.frame(results$fitTable)}
#'
#' @export
itemOrder <- function(
    data,
    vars,
    tolerance = 10,
    hMin = 0.3,
    showHasse = TRUE,
    showImplications = TRUE,
    showScales = TRUE,
    showPatterns = FALSE,
    patternsN = 10,
    highlight = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("itemOrder requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- itemOrderOptions$new(
        vars = vars,
        tolerance = tolerance,
        hMin = hMin,
        showHasse = showHasse,
        showImplications = showImplications,
        showScales = showScales,
        showPatterns = showPatterns,
        patternsN = patternsN,
        highlight = highlight)

    analysis <- itemOrderClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

